  'eventBus',
  'bpmnReplace'
];

inherits(AttachEventBehavior, CommandInterceptor);



// helper /////
function getEventDefinition(element) {
  var bo = getBusinessObject(element);

  return bo && bo.eventDefinitions && bo.eventDefinitions[0];
}

